n=22
out=[[5]*n for _ in range(n)]
# (top row, left col, frame, center)
panels=[(2,0,8,4),(0,12,2,1),(2,17,2,3),(8,0,8,3),(8,17,2,9),(14,0,8,7),(14,17,2,7),(16,5,8,9)]
for r0,c0,frame,center in panels:
    for dr in range(5):
        for dc in range(5):
            out[r0+dr][c0+dc]=center if 1<=dr<=3 and 1<=dc<=3 else frame
print('\n'.join(' '.join(map(str,row)) for row in out))
